package vn.edu.eaut.lab8.bean; import jakarta.enterprise.context.SessionScoped; import jakarta.inject.Named; import jakarta.faces.application.FacesMessage; import jakarta.faces.context.FacesContext; import vn.edu.eaut.lab8.model.Sach; import java.io.Serializable; import java.util.*; @Named("sachBean") @SessionScoped public class SachBean implements Serializable { private List<Sach> ds=new ArrayList<>(); private Sach sach=new Sach(); private int next=1; public String save(){sach.setId(next++);ds.add(sach);msg("Thành công","Đã lưu sách");sach=new Sach();return null;} public void delete(int id){ds.removeIf(x->x.getId()==id);msg("Thành công","Đã xóa sách");} public List<Sach>getDs(){return ds;}public Sach getSach(){return sach;}public void setSach(Sach x){sach=x;}private void msg(String a,String b){FacesContext.getCurrentInstance().addMessage(null,new FacesMessage(FacesMessage.SEVERITY_INFO,a,b));} }
